use kni_geometry_prototypes::*;
fn rect(w:f64,y:f64)->Geometry{let p=|x,y|Point{x,y};Geometry{advance:w+2.,rings:vec![Ring{start:p(0.,y),spans:vec![Span::Line(p(w,y)),Span::Line(p(w,y+10.)),Span::Line(p(0.,y+10.)),Span::Line(p(0.,y))]}]}}
fn rule()->Rule{Rule{minimum_training:4,gauge_statistic:GaugeStatistic::Median,maximum_unique_training:8192,coverage_numerator:1,coverage_denominator:2,flatten_fraction:1./1024.,bootstrap_replicates:4,stability_fraction:0.5}}
#[test]fn supplement_leaves_every_production_receipt_and_pin_unchanged(){let r=rule();let train=[2.,2.1,2.2,8.,8.1,8.2].map(|x|rect(x,0.));let a=fit(&train,r.clone(),&r.pin()).unwrap();let queries=[rect(2.05,0.),rect(2.05,1.)];let before=(r.canonical(),r.pin(),a.pin().to_owned(),a.canonical_receipt().unwrap(),a.query_receipt(&queries));let supplement=a.sensitivity_receipt(&queries);assert!(supplement.contains("threshold=1/4"));assert!(supplement.contains("threshold=3/4"));assert!(supplement.contains("q=9/10"));assert!(supplement.contains("illustrative_not_precision"));assert!(supplement.contains("diagnostic_reason=zero_range_exact_equality_mismatch"));assert_eq!(before,(r.canonical(),r.pin(),a.pin().to_owned(),a.canonical_receipt().unwrap(),a.query_receipt(&queries)));let reversed=[queries[1].clone(),queries[0].clone()];assert_eq!(supplement,a.sensitivity_receipt(&reversed));}
